def try_shift_down(grid, bg):
    """Shift all non-bg values down by 1, bg filling above, clipped"""
    h = len(grid)
    w = len(grid[0])
    new_grid = [[bg for _ in range(w)] for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                # Shift to r+1 if possible
                nr = min(r + 1, h - 1)
                new_grid[nr][c] = grid[r][c]

    return new_grid

