def trace_paths(grid_in, grid_out, bg):
    """Find where each non-bg value in input goes in output"""
    h, w = len(grid_in), len(grid_in[0])
    paths = {}  # (r,c) in input -> (nr,nc) in output

    for r in range(h):
        for c in range(w):
            val = grid_in[r][c]
            if val != bg:
                # Find where this value appears in output
                found = []
                for nr in range(h):
                    for nc in range(w):
                        if grid_out[nr][nc] == val:
                            found.append((nr, nc))
                if len(found) == 1:
                    paths[(r, c)] = found[0]
                elif len(found) > 1:
                    # Multiple targets with same value
                    if val not in paths:
                        paths[(r, c)] = None  # ambiguous

    return paths

